    if STAGE >= 2:
        r['combinable'] = [['b', 'a']]
    if STAGE >= 3:
        r['manager_user_ids'] = ['guest']
    return {'users': [{'id': 'guest', 'email': 'guest@numeric.test', 'password': 'synthetic-numeric-password', 'display_name': 'Guest'}],
            'restaurants': [r], 'reservations': []}


