            else:
                count = obj.gap
                zeros = '0' * 65536
                while count:
                    size = min(count, len(zeros))
                    yield zeros[:size]
                    count -= size
            yield obj.low
            if obj.exponent:
                yield 'e' + str(obj.exponent)
        elif type(obj) is int:
