                stack.append(('value', obj[j]))
                if j:
                    stack.append(('literal', ','))
        elif type(obj) is dict:
            yield '{'
            stack.append(('literal', '}'))
            keys = sorted(obj) if canonical else list(obj)
            for j in range(len(keys) - 1, -1, -1):
                key = keys[j]
                if type(key) is not str:
